import {weatherCat as cat} from '../pixel/cats.js';
import {catWeather} from '../city/atmosphere.js';
import {state,esc} from '../../lib/store.js';import {weatherText} from '../../lib/services.js';import {panel,icon,button,badge} from '../pixel/primitives.js';
export function weatherPanel(){const w=state.weather;let content=`<div class="weather-placeholder"><div class="weather-now">${icon('cloud',54)}<div><strong>--°C</strong><p>尚未选择城市</p></div></div><div class="weather-detail"><div><span>体感</span>--°C</div><div><span>湿度</span>--%</div><div><span>风速</span>-- km/h</div><div><span>降雨概率</span>--%</div></div><div class="placeholder-days">${Array.from({length:5},(_,i)=>`<span>${i===0?'今天':i+' 天后'}${icon('cloud',20)}-- / --</span>`).join('')}</div><div class="cat-advice">${cat(false)}<p>选择城市后，天气助手会给出真实出行建议。</p></div></div><p class="muted small">选择城市或主动授权当前位置。不会自动读取精确位置。</p><div class="actions">${button('选择城市','city-search','','primary')}${button('使用当前位置','geolocate')}</div><p class="micro muted">定位只在你点击后请求；近似到约 1 km 的坐标发送至 Open-Meteo 获取天气。</p>`;if(w){const d=w.daily,c=w.current,rain=d.precipitation_probability_max?.[0]??0,drop=d.temperature_2m_max[0]-d.temperature_2m_max[1];const name=weatherText(c.weather_code);const outfit=c.apparent_temperature<10?'外套与保暖层；注意防寒。':c.apparent_temperature<20?'长袖与轻外套，注意早晚温差。':c.apparent_temperature<28?'轻薄衣物；早晚可备薄外套。':'透气轻薄衣物；注意补水防晒。';content=`<div class="row"><h3>${esc(w.city)}</h3>${badge(Date.now()-w.fetchedAt>3600000?'缓存 · 建议刷新':'LIVE API','cyan')}</div><div class="weather-now">${icon(c.weather_code===0?'sun':c.weather_code<4?'cloud':'rain',54)}<div><strong>${Math.round(c.temperature_2m)}°C</strong><p class="muted mt">${name}</p></div></div><div class="weather-detail"><div><span>体感</span>${c.apparent_temperature}°C</div><div><span>湿度</span>${c.relative_humidity_2m}%</div><div><span>今日降雨概率</span>${rain}%</div><div><span>风速</span>${c.wind_speed_10m} km/h</div><div><span>今日最高 UV</span>${d.uv_index_max[0]}</div><div><span>更新时间</span>${new Date(w.fetchedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</div></div><div class="forecast">${d.time.map((date,i)=>`<div>${i===0?'今天':date.slice(5)}${icon(d.weather_code[i]===0?'sun':d.weather_code[i]<4?'cloud':'rain',20)}<b>${Math.round(d.temperature_2m_min[i])}° / ${Math.round(d.temperature_2m_max[i])}°</b>${d.precipitation_probability_max[i]}% 雨</div>`).join('')}</div><div class="notice">${cat(catWeather(w))}<b class="orange mono">出行建议</b><br>${outfit}<br>${rain>=40?'今天建议带伞。':'今天降雨概率较低。'}${drop>=5?`<br>明天最高温预计下降 ${drop.toFixed(0)}°C，记得添衣。`:''}${d.wind_speed_10m_max[0]>=40?'<br>预计风力较强，注意出行。':''}${c.weather_code>=95?'<br>雷暴天气：减少不必要的户外活动。':''}<div class="micro mt">根据预报自动生成，仅为生活提示，不是官方气象预警。</div></div><div class="actions">${button('刷新天气','weather-refresh')}${button('更换城市','city-search')}</div><p class="micro muted mt">${new Date(w.fetchedAt).toLocaleString('zh-CN')} · 预报时区 ${esc(w.timezone)}<br><a href="https://open-meteo.com/" target="_blank" rel="noopener">Weather data: Open-Meteo / CC BY 4.0</a></p>`}return panel('WEATHER.exe',content)}
export const cityForm=()=>`<form data-form="city"><label class="field"><span>城市名（中文或英文）</span><input name="name" placeholder="例如：Lisbon / 上海" required minlength="2"></label><button class="button primary">搜索城市</button></form><div id="city-results" class="mt" role="status"></div>`;
